insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('organization-logos','organization-logos',true,2097152,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=true,file_size_limit=2097152,allowed_mime_types=array['image/jpeg','image/png','image/webp'];
drop policy if exists "Organization owners upload logos" on storage.objects;
create policy "Organization owners upload logos" on storage.objects for insert to authenticated with check(bucket_id='organization-logos' and exists(select 1 from public.organizations o where o.id::text=(storage.foldername(name))[1] and o.owner_id=auth.uid()));
drop policy if exists "Organization owners update logos" on storage.objects;
create policy "Organization owners update logos" on storage.objects for update to authenticated using(bucket_id='organization-logos' and exists(select 1 from public.organizations o where o.id::text=(storage.foldername(name))[1] and o.owner_id=auth.uid())) with check(bucket_id='organization-logos' and exists(select 1 from public.organizations o where o.id::text=(storage.foldername(name))[1] and o.owner_id=auth.uid()));
drop policy if exists "Organization owners delete logos" on storage.objects;
create policy "Organization owners delete logos" on storage.objects for delete to authenticated using(bucket_id='organization-logos' and exists(select 1 from public.organizations o where o.id::text=(storage.foldername(name))[1] and o.owner_id=auth.uid()));